async function checkIIHS(path) {
  const url = `https://www.iihs.org/ratings/vehicle/${path}`;
  const res = await tool.fetch_url({ url });
  if (res.status !== 200) return { path, status: res.status };
  // Extract award and ratings
  const text = res.body;
  const isTSP = text.includes("TOP SAFETY PICK+");
  const isTSPRegular = text.includes("TOP SAFETY PICK");
  let award = "None / Not awarded";
  if (isTSP) award = "TOP SAFETY PICK+";
  else if (isTSPRegular) award = "TOP SAFETY PICK";

  // match ratings
  const smallOverlap = text.match(/Small overlap front[\s\S]{0,100}?(Good|Acceptable|Marginal|Poor)/i)?.[1];
  const modOverlap = text.match(/Moderate overlap front[\s\S]{0,100}?(Good|Acceptable|Marginal|Poor)/i)?.[1];
  const side = text.match(/Side: updated test[\s\S]{0,100}?(Good|Acceptable|Marginal|Poor)/i)?.[1];

  return { path, status: res.status, award, smallOverlap, modOverlap, side };
}

