const tabId = 2017691979;
const edmundsReview = await browserjs(tabId, () => {
  const headings = Array.from(document.querySelectorAll('h2, h3, h4'));
  const prosH = headings.find(h => /pros/i.test(h.textContent));
  const consH = headings.find(h => /cons/i.test(h.textContent));
  const verdictH = headings.find(h => /verdict|edmunds says/i.test(h.textContent));

  return {
    prosText: prosH ? prosH.parentElement?.innerText : null,
    consText: consH ? consH.parentElement?.innerText : null,
    verdictText: verdictH ? verdictH.parentElement?.innerText : null,
    allHeadings: headings.map(h => h.textContent.trim())
  };
});
