const tabId = 2017691980;
const priusSpecsText = await browserjs(tabId, () => {
  const headings = Array.from(document.querySelectorAll('h2, h3, h4'));
  const specH2 = headings.find(h => h.innerText.includes('Prius Specs'));
  if (specH2) {
    let parent = specH2.parentElement;
    for (let i = 0; i < 4; i++) {
      if (parent && parent.innerText.length > 500) break;
      if (parent) parent = parent.parentElement;
    }
    return parent ? parent.innerText : "No parent text";
  }
  return "Not found";
});
console.log("Prius Specs text:\n", priusSpecsText.slice(0, 3000));

