// Let's check NHTSA API for 2025/2024 Honda Civic
const nhtsaCivic = await tool.fetch_url({
  url: "https://api.nhtsa.gov/SafetyRatings/modelyear/2025/make/HONDA/model/CIVIC?format=json"
});
console.log("NHTSA Civic response status:", nhtsaCivic?.status);
let civicVehicles = [];
try {
  const data = JSON.parse(nhtsaCivic.body);
  console.log("NHTSA Civic count:", data.Count, data.Results);
  civicVehicles = data.Results;
} catch (e) {
  console.log("Error parsing NHTSA JSON:", e);
}

// Let's fetch details for the first vehicleId if available
if (civicVehicles.length > 0) {
  const vId = civicVehicles[0].VehicleId;
  const detail = await tool.fetch_url({
    url: `https://api.nhtsa.gov/SafetyRatings/VehicleId/${vId}?format=json`
  });
  const detailData = JSON.parse(detail.body);
  console.log("NHTSA Civic Detail:", {
    VehicleDescription: detailData.Results[0]?.VehicleDescription,
    OverallRating: detailData.Results[0]?.OverallRating,
    OverallFrontCrashRating: detailData.Results[0]?.OverallFrontCrashRating,
    OverallSideCrashRating: detailData.Results[0]?.OverallSideCrashRating,
    RolloverRating: detailData.Results[0]?.RolloverRating,
  });
}

