async function checkNHTSA(year, make, model) {
  const url = `https://api.nhtsa.gov/SafetyRatings/modelyear/${year}/make/${encodeURIComponent(make)}/model/${encodeURIComponent(model)}?format=json`;
  const res = await tool.fetch_url({ url });
  try {
    const data = JSON.parse(res.body);
    if (!data.Results || data.Results.length === 0) return { year, make, model, count: 0, status: "Not evaluated or not shown" };
    const vId = data.Results[0].VehicleId;
    const detailRes = await tool.fetch_url({ url: `https://api.nhtsa.gov/SafetyRatings/VehicleId/${vId}?format=json` });
    const detail = JSON.parse(detailRes.body).Results[0];
    return {
      year,
      make,
      model,
      vehicleDescription: detail?.VehicleDescription,
      overallRating: detail?.OverallRating || "Not Rated",
      frontalCrash: detail?.OverallFrontCrashRating || "Not Rated",
      sideCrash: detail?.OverallSideCrashRating || "Not Rated",
      rollover: detail?.RolloverRating || "Not Rated"
    };
  } catch (e) {
    return { year, make, model, error: e.message };
  }
}

